-- Restore the complete Outland mining pool topology from YTDB R667.
--
-- MaNGOS Four's baseline inherited an older YTDB snapshot with 610 empty
-- child templates, 383 unpooled primary deposits, and missing alternate
-- Khorium/Rich Adamantite spawns. YTDB 0.15.4 R667 is the direct successor
-- of that data: it preserves every current logical mining coordinate, adds
-- 16 Isle of Quel'Danas nodes, and supplies the complete pool membership.
--
-- Source:
--   NeatElves/wotlk-ytdbdb
--   Full_DB/YTDB_0.15.4_R667_cMaNGOS_R14092_RuDB_R74.sql.gz
--
-- Pool ids 50000-51319 and 52000-52260 are reserved by this migration.
-- Missing gameobject GUIDs are allocated above the current maximum so that
-- later content which reused 182 historical YTDB GUIDs is never overwritten.

DROP TEMPORARY TABLE IF EXISTS `_outland_ore_pool_source`;
CREATE TEMPORARY TABLE `_outland_ore_pool_source`
(
    `source_pool_id` MEDIUMINT UNSIGNED NOT NULL,
    `child_max_limit` INT UNSIGNED NOT NULL,
    `child_description` VARCHAR(255) NOT NULL,
    `source_mother_pool` MEDIUMINT UNSIGNED NULL,
    `mother_max_limit` INT UNSIGNED NULL,
    `mother_description` VARCHAR(255) NULL,
    `relation_chance` FLOAT NULL,
    `relation_description` VARCHAR(255) NULL,
    PRIMARY KEY (`source_pool_id`)
) ENGINE=InnoDB;

     `source_mother_pool`, `mother_max_limit`, `mother_description`,
     `relation_chance`, `relation_description`)
