DROP TEMPORARY TABLE IF EXISTS `_outland_ore_member_source`;
CREATE TEMPORARY TABLE `_outland_ore_member_source`
(
    `sequence_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `source_guid` INT UNSIGNED NOT NULL,
    `source_pool_id` MEDIUMINT UNSIGNED NOT NULL,
    `chance` FLOAT NOT NULL,
    `description` VARCHAR(255) NOT NULL,
    `resolved_guid` INT UNSIGNED NULL,
    PRIMARY KEY (`sequence_id`),
    UNIQUE KEY `uq_source_guid` (`source_guid`),
    KEY `idx_source_pool` (`source_pool_id`)
) ENGINE=InnoDB;


-- Only rows absent from the MaNGOS Four baseline (plus one corrected Z
-- coordinate) need full spawn data. Existing rows retain their local
-- zone/area metadata and schema-specific fields.
DROP TEMPORARY TABLE IF EXISTS `_outland_ore_spawn_source`;
CREATE TEMPORARY TABLE `_outland_ore_spawn_source`
(
    `source_guid` INT UNSIGNED NOT NULL,
    `id` MEDIUMINT UNSIGNED NOT NULL,
    `map_id` SMALLINT UNSIGNED NOT NULL,
    `zone_id` INT UNSIGNED NOT NULL,
    `area_id` INT UNSIGNED NOT NULL,
    `spawn_mask` INT NOT NULL,
    `phase_mask` INT UNSIGNED NOT NULL,
    `position_x` FLOAT NOT NULL,
    `position_y` FLOAT NOT NULL,
    `position_z` FLOAT NOT NULL,
    `orientation` FLOAT NOT NULL,
    `rotation0` FLOAT NOT NULL,
    `rotation1` FLOAT NOT NULL,
    `rotation2` FLOAT NOT NULL,
    `rotation3` FLOAT NOT NULL,
    `spawntimesecs` INT NOT NULL,
    `animprogress` TINYINT UNSIGNED NOT NULL,
    `state` TINYINT UNSIGNED NOT NULL,
    PRIMARY KEY (`source_guid`)
) ENGINE=InnoDB;

     `spawn_mask`, `phase_mask`, `position_x`, `position_y`,
     `position_z`, `orientation`, `rotation0`, `rotation1`,
     `rotation2`, `rotation3`, `spawntimesecs`, `animprogress`,
