-- Capture both the 610 empty templates and the 922 populated legacy children.
SELECT `entry`
FROM `pool_template`
WHERE `entry` < 50000
  AND `description` IN
  (
      'GO 175404,[2047,2040],map=530',
      'GO 181555,181557 map=530',
      'GO 181556,181569,181557 map=530'
  );

SELECT DISTINCT `pg`.`pool_entry`
FROM `pool_gameobject` `pg`
INNER JOIN `gameobject` `go` ON `go`.`guid` = `pg`.`guid`
WHERE `pg`.`pool_entry` < 50000
  AND `go`.`map` = 530
  AND `go`.`id` IN (2040, 2047, 175404, 181555, 181556, 181557, 181569);

DROP TEMPORARY TABLE IF EXISTS `_outland_ore_legacy_mother`;
CREATE TEMPORARY TABLE `_outland_ore_legacy_mother`
(
    `pool_id` MEDIUMINT UNSIGNED NOT NULL,
    PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB;

SELECT DISTINCT `pp`.`mother_pool`
FROM `pool_pool` `pp`
INNER JOIN `_outland_ore_legacy_child` `child`
    ON `child`.`pool_id` = `pp`.`pool_id`;

-- Remove only old memberships and hierarchy links. Gameobjects are preserved.
DELETE `pg`
FROM `pool_gameobject` `pg`
INNER JOIN `gameobject` `go` ON `go`.`guid` = `pg`.`guid`
WHERE `go`.`map` = 530
  AND `go`.`id` IN (2040, 2047, 175404, 181555, 181556, 181557, 181569);

DELETE `pp`
FROM `pool_pool` `pp`
INNER JOIN `_outland_ore_legacy_child` `child`
    ON `child`.`pool_id` = `pp`.`pool_id`;

DELETE `template`
FROM `pool_template` `template`
INNER JOIN `_outland_ore_legacy_child` `child`
    ON `child`.`pool_id` = `template`.`entry`;

-- Ten old mothers also own unrelated children. Keep them; remove only mothers
-- which became completely unreferenced after detaching the ore children.
DELETE `template`
FROM `pool_template` `template`
INNER JOIN `_outland_ore_legacy_mother` `legacy`
    ON `legacy`.`pool_id` = `template`.`entry`
LEFT JOIN `pool_pool` `as_mother`
    ON `as_mother`.`mother_pool` = `template`.`entry`
LEFT JOIN `pool_pool` `as_child`
    ON `as_child`.`pool_id` = `template`.`entry`
LEFT JOIN `pool_gameobject` `direct_go`
    ON `direct_go`.`pool_entry` = `template`.`entry`
LEFT JOIN `pool_creature` `direct_creature`
    ON `direct_creature`.`pool_entry` = `template`.`entry`
WHERE `as_mother`.`pool_id` IS NULL
  AND `as_child`.`pool_id` IS NULL
  AND `direct_go`.`guid` IS NULL
  AND `direct_creature`.`guid` IS NULL;

-- Make reapplication idempotent without touching unrelated occupants of the
-- reserved ranges. A foreign collision causes the later INSERT to fail.
DELETE `pp`
FROM `pool_pool` `pp`
LEFT JOIN `pool_template` `child_template`
    ON `child_template`.`entry` = `pp`.`pool_id`
LEFT JOIN `pool_template` `mother_template`
    ON `mother_template`.`entry` = `pp`.`mother_pool`
WHERE LEFT(COALESCE(`child_template`.`description`, ''), 11) = 'YTDB R667: '
   OR LEFT(COALESCE(`mother_template`.`description`, ''), 11) = 'YTDB R667: ';

DELETE FROM `pool_template`
WHERE LEFT(`description`, 11) = 'YTDB R667: '
  AND ((`entry` BETWEEN 50000 AND 51319)
    OR (`entry` BETWEEN 52000 AND 52260));

-- Resolve every source object to its existing local GUID when possible.
UPDATE `_outland_ore_member_source` `member`
INNER JOIN `gameobject` `existing`
    ON `existing`.`guid` = `member`.`source_guid`
   AND `existing`.`map` = 530
   AND `existing`.`id` IN (2040, 2047, 175404, 181555, 181556, 181557, 181569)
SET `member`.`resolved_guid` = `existing`.`guid`;

-- On a repeated run, restored rows have dynamically allocated GUIDs. Match
-- those rows by object id and position instead of allocating duplicates.
UPDATE `_outland_ore_member_source` `member`
INNER JOIN
(
    SELECT `source`.`source_guid`, MIN(`existing`.`guid`) AS `resolved_guid`
    FROM `_outland_ore_spawn_source` `source`
    INNER JOIN `gameobject` `existing`
        ON `existing`.`id` = `source`.`id`
       AND `existing`.`map` = `source`.`map_id`
       AND ABS(`existing`.`position_x` - `source`.`position_x`) < 0.01
       AND ABS(`existing`.`position_y` - `source`.`position_y`) < 0.01
       AND ABS(`existing`.`position_z` - `source`.`position_z`) < 0.01
    GROUP BY `source`.`source_guid`
) `matched` ON `matched`.`source_guid` = `member`.`source_guid`
SET `member`.`resolved_guid` = `matched`.`resolved_guid`
WHERE `member`.`resolved_guid` IS NULL;

SET @outland_ore_guid_start := (SELECT COALESCE(MAX(`guid`), 0) FROM `gameobject`);

UPDATE `_outland_ore_member_source`
SET `resolved_guid` = @outland_ore_guid_start + `sequence_id`
WHERE `resolved_guid` IS NULL;

     `phaseMask`, `phaseId`, `phaseGroup`, `position_x`, `position_y`,
     `position_z`, `orientation`, `rotation0`, `rotation1`, `rotation2`,
     `rotation3`, `spawntimesecs`, `animprogress`, `state`, `ScriptName`,
     `VerifiedBuild`)
SELECT
    `member`.`resolved_guid`, `source`.`id`, `source`.`map_id`,
    `source`.`zone_id`, `source`.`area_id`, `source`.`spawn_mask`,
    `source`.`phase_mask`, 0, 0, `source`.`position_x`,
    `source`.`position_y`, `source`.`position_z`, `source`.`orientation`,
    `source`.`rotation0`, `source`.`rotation1`, `source`.`rotation2`,
    `source`.`rotation3`, `source`.`spawntimesecs`,
    `source`.`animprogress`, `source`.`state`, '', 0
FROM `_outland_ore_spawn_source` `source`
INNER JOIN `_outland_ore_member_source` `member`
    ON `member`.`source_guid` = `source`.`source_guid`
LEFT JOIN `gameobject` `existing`
    ON `existing`.`guid` = `member`.`resolved_guid`
WHERE `existing`.`guid` IS NULL;

-- Apply the trusted geometry, including the corrected Z coordinate at
-- (-987.794, 1876.03), while retaining local zone/area and phase conventions.
UPDATE `gameobject` `go`
INNER JOIN `_outland_ore_member_source` `member`
    ON `member`.`resolved_guid` = `go`.`guid`
INNER JOIN `_outland_ore_spawn_source` `source`
    ON `source`.`source_guid` = `member`.`source_guid`
   AND `source`.`id` = `go`.`id`
SET `go`.`position_x` = `source`.`position_x`,
    `go`.`position_y` = `source`.`position_y`,
    `go`.`position_z` = `source`.`position_z`,
    `go`.`orientation` = `source`.`orientation`,
    `go`.`rotation0` = `source`.`rotation0`,
    `go`.`rotation1` = `source`.`rotation1`,
    `go`.`rotation2` = `source`.`rotation2`,
    `go`.`rotation3` = `source`.`rotation3`;

DROP TEMPORARY TABLE IF EXISTS `_outland_ore_child_map`;
CREATE TEMPORARY TABLE `_outland_ore_child_map`
(
    `sequence_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `source_pool_id` MEDIUMINT UNSIGNED NOT NULL,
    `resolved_pool_id` MEDIUMINT UNSIGNED NULL,
    PRIMARY KEY (`sequence_id`),
    UNIQUE KEY `uq_source_pool` (`source_pool_id`),
    UNIQUE KEY `uq_resolved_pool` (`resolved_pool_id`)
) ENGINE=InnoDB;

SELECT `source_pool_id`
FROM `_outland_ore_pool_source`
ORDER BY `source_pool_id`;

UPDATE `_outland_ore_child_map`
SET `resolved_pool_id` = 49999 + `sequence_id`;

DROP TEMPORARY TABLE IF EXISTS `_outland_ore_mother_map`;
CREATE TEMPORARY TABLE `_outland_ore_mother_map`
(
    `sequence_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
    `source_pool_id` MEDIUMINT UNSIGNED NOT NULL,
    `resolved_pool_id` MEDIUMINT UNSIGNED NULL,
    PRIMARY KEY (`sequence_id`),
    UNIQUE KEY `uq_source_pool` (`source_pool_id`),
    UNIQUE KEY `uq_resolved_pool` (`resolved_pool_id`)
) ENGINE=InnoDB;

SELECT DISTINCT `source_mother_pool`
FROM `_outland_ore_pool_source`
WHERE `source_mother_pool` IS NOT NULL
ORDER BY `source_mother_pool`;

UPDATE `_outland_ore_mother_map`
SET `resolved_pool_id` = 51999 + `sequence_id`;

SELECT
    `map`.`resolved_pool_id`,
    `source`.`child_max_limit`,
    CONCAT('YTDB R667: ', `source`.`child_description`)
FROM `_outland_ore_pool_source` `source`
INNER JOIN `_outland_ore_child_map` `map`
    ON `map`.`source_pool_id` = `source`.`source_pool_id`
ORDER BY `map`.`resolved_pool_id`;

SELECT
    `map`.`resolved_pool_id`,
    MIN(`source`.`mother_max_limit`),
    CONCAT('YTDB R667: ', MIN(`source`.`mother_description`))
FROM `_outland_ore_mother_map` `map`
INNER JOIN `_outland_ore_pool_source` `source`
    ON `source`.`source_mother_pool` = `map`.`source_pool_id`
GROUP BY `map`.`resolved_pool_id`
ORDER BY `map`.`resolved_pool_id`;

SELECT
    `member`.`resolved_guid`,
    `map`.`resolved_pool_id`,
    `member`.`chance`,
    `member`.`description`
FROM `_outland_ore_member_source` `member`
INNER JOIN `_outland_ore_child_map` `map`
    ON `map`.`source_pool_id` = `member`.`source_pool_id`
ORDER BY `map`.`resolved_pool_id`, `member`.`source_guid`;

SELECT
    `child_map`.`resolved_pool_id`,
    `mother_map`.`resolved_pool_id`,
    `source`.`relation_chance`,
    `source`.`relation_description`
FROM `_outland_ore_pool_source` `source`
INNER JOIN `_outland_ore_child_map` `child_map`
    ON `child_map`.`source_pool_id` = `source`.`source_pool_id`
INNER JOIN `_outland_ore_mother_map` `mother_map`
    ON `mother_map`.`source_pool_id` = `source`.`source_mother_pool`
ORDER BY `mother_map`.`resolved_pool_id`, `child_map`.`resolved_pool_id`;

DROP TEMPORARY TABLE `_outland_ore_mother_map`;
DROP TEMPORARY TABLE `_outland_ore_child_map`;
DROP TEMPORARY TABLE `_outland_ore_legacy_mother`;
DROP TEMPORARY TABLE `_outland_ore_legacy_child`;
DROP TEMPORARY TABLE `_outland_ore_spawn_source`;
DROP TEMPORARY TABLE `_outland_ore_member_source`;
DROP TEMPORARY TABLE `_outland_ore_pool_source`;

